text:
        priority: CascadePriority,
    ) {
        self.cascade
            .cascade_custom_property(context, declaration, priority);
    }

    /// Prepares typed attributes referenced by an ordinary keyframe declaration.
    pub fn prepare_attributes(
        &mut self,
        context: &mut computed::Context,
        value: &'a UnparsedValue,
        attribute_tracker: &mut AttributeTracker,
    ) {
        self.cascade
            .update_attributes_map(context, &value.variable_value, attribute_tracker);
    }

    /// Resolves the cascaded custom properties into `context.builder.substitution_functions`.
    pub fn build(
        mut self,
        context: &mut computed::Context,
        attribute_tracker: &mut AttributeTracker,
    ) {
        self.cascade.apply_custom_and_prioritary_properties(
            context,
            &self.decls,
            &mut self.shorthand_cache,
            attribute_tracker,
        );
    }
}

fn substitute_variables_if_needed<'cache, 'decl>(
    &self,
    context: &mut computed::Context,
    shorthand_cache: &'cache mut ShorthandsWithPropertyReferencesCache,
    declaration: &'decl PropertyDeclaration,
    attribute_tracker: &mut AttributeTracker,
) -> Cow<'decl, PropertyDeclaration>
where
    'cache: 'decl,
{
    let declaration = match *declaration {
        PropertyDeclaration::WithVariables(ref declaration) => declaration,
        ref d => return Cow::Borrowed(d),
    };

    if !declaration.id.inherited() {
        context.rule_cache_conditions.borrow_mut().set_uncacheable();

        // NOTE(emilio): We only really need to add the `display` /
        // `content` flag if the CSS variable has not been specified on our
        // declarations, but we don't have that information at this point,
        // and it doesn't seem like an important enough optimization to
        // warrant it.
        if matches!(declaration.id, LonghandId::Display | LonghandId::Content) {
            context
                .builder
                .add_flags(ComputedValueFlags::DISPLAY_OR_CONTENT_DEPEND_ON_INHERITED_STYLE);
        }
    }

    debug_assert!(
        context.builder.stylist.is_some(),
        "Need a Stylist to substitute variables!"
    );
    declaration.substitute_variables(
        context.builder.substitution_functions(),
        context.builder.stylist.unwrap(),
        context,
        shorthand_cache,
        attribute_tracker,
    )
}

fn apply_one_prioritary_property(
    &mut self,
    context: &mut computed::Context,
    decls: &Declarations,
    cache: &mut ShorthandsWithPropertyReferencesCache,
    id: PrioritaryPropertyId,
    attr_provider: &mut AttributeTracker,
) {
    let mut index = decls.prioritary_positions[id as usize].most_important;
    if index == DeclarationIndex::MAX {
        return;
    }

    let longhand_id = id.to_longhand();
    debug_assert!(
        !longhand_id.is_logical(),
        "That could require more book-keeping"
    );
    loop {
        let decl = decls.longhand_declarations[index as usize];
        self.apply_one_longhand(
            context,
            longhand_id,
            decl.decl,
            decl.priority,
            cache,
            attr_provider,
        );
        if self.seen.longhands.contains(longhand_id) {
            // Found it!
            self.did_apply_prioritary_property(context, id);
            return;
        }
        debug_assert!(
            decl.next_index == 0 || decl.next_index > index,
            "should make progress! {} -> {}",
            index,
            decl.next_index,
        );
        index = decl.next_index;
        if index == 0 {
            return;
        }
    }
}

fn apply_one_longhand(
    &mut self,
    context: &mut computed::Context,
    longhand_id: LonghandId,
    declaration: &PropertyDeclaration,
    priority: CascadePriority,
    cache: &mut ShorthandsWithPropertyReferencesCache,
    attribute_tracker: &mut AttributeTracker,
) {
    debug_assert!(!longhand_id.is_logical());
    if self.seen.longhands.contains(longhand_id) {
        return;
    }

    if !(priority.flags() - context.included_cascade_flags).is_empty() {
        return;
    }

    if self.reverted.longhands_set.contains(longhand_id)
        && let Some(&(reverted_priority, revert_kind)) =
            self.reverted.longhands.get(&longhand_id)
        && !reverted_priority.allows_when_reverted(&priority, revert_kind)
    {
        return;
    }

    let mut declaration =
        self.substitute_variables_if_needed(context, cache, declaration, attribute_tracker);

    // When document colors are disabled, do special handling of
    // properties that are marked as ignored in that mode.
    let origin = priority.cascade_level().origin();
    if self.ignore_colors {
        tweak_when_ignoring_colors(
            context,
            longhand_id,
            origin,
            &mut declaration,
            &mut self.declarations_to_apply_unless_overridden,
        );
    }
    let can_skip_apply = match declaration.get_css_wide_keyword() {
        Some(keyword) => {
            if let Some(revert_kind) = keyword.revert_kind() {
                // We intentionally don't want to insert it into
                // `self.seen.longhands`, `reverted` takes care of rejecting
                // other declarations as needed.
                self.reverted.longhands_set.insert(longhand_id);
                self.reverted
                    .longhands
                    .insert(longhand_id, (priority, revert_kind));
                return;
            }

            let inherited = longhand_id.inherited();
            let zoomed = !context.builder.effective_zoom_for_inheritance.is_one()
                && longhand_id.zoom_dependent();
            match keyword {
                CSSWideKeyword::Revert
                | CSSWideKeyword::RevertLayer
                | CSSWideKeyword::RevertRule => unreachable!(),
                CSSWideKeyword::Unset => !zoomed || !inherited,
                CSSWideKeyword::Inherit => inherited && !zoomed,
                CSSWideKeyword::Initial => !inherited,
            }
        },
        None => false,
    };

    self.seen.longhands.insert(longhand_id);
    if origin != CascadeOrigin::UA {
        self.author_or_user_specified.insert(longhand_id);
    }

    if !can_skip_apply {
        // Set context.scope to this declaration's cascade level so that
        // tree-scoped properties (anchor-name, position-anchor, anchor-scope)
        // get the correct scope when converted to computed values.
        let old_scope = context.scope;
        let cascade_level = priority.cascade_level();
        context.scope = cascade_level;
        unsafe { self.do_apply_declaration(context, longhand_id, &declaration) }
        context.scope = old_scope;
    }
}

// The cycle dependencies removal in this function is a variant
// of Tarjan's algorithm. It is mostly based on the pseudo-code
// listed in
// https://en.wikipedia.org/w/index.php?
// title=Tarjan%27s_strongly_connected_components_algorithm&oldid=801728495

#[derive(Clone, Eq, PartialEq, Debug)]
enum VarType {
    Attr(Name, Namespace),
    Custom(Name),
    NonCustom(SingleNonCustomReference),
}

impl VarType {
    fn namespace(&self) -> Option<&Namespace> {
        match self {
            Self::Attr(_, namespace) => Some(namespace),
            _ => None,
        }
    }
}

/// Struct recording necessary information for each variable.
#[derive(Debug)]
struct VarInfo {
    /// The name of the variable. It will be taken when the corresponding variable is popped
    /// from the stack, which serves as a mark for whether the variable is currently in the
    /// stack below.
    var: Option<VarType>,
    /// If the variable is in a dependency cycle, lowlink represents a smaller index which
    /// corresponds to a variable in the same strong connected component, which is known to be
    /// accessible from this variable. It is not necessarily the root, though.
    lowlink: usize,
}

#[derive(Debug, Default)]
struct OrderIndexMap {
    /// The map from the custom property name to its order index.
    var: PrecomputedHashMap<Name, usize>,
    /// The map from the attribute name to its order index.
    attr: PrecomputedHashMap<Namespace, PrecomputedHashMap<Name, usize>>,
}

impl OrderIndexMap {
    fn clear(&mut self) {
        self.var.clear();
        self.attr.clear();
    }
}

/// Context struct for traversing the variable graph, so that we can
/// avoid referencing all the fields multiple times.
struct Context<'a, 'b: 'a, 'c, 'd> {
    /// Number of variables visited. This is used as the order index
    /// when we visit a new unresolved variable.
    count: usize,
    /// The map from a substitution function name to its order index.
    index_map: OrderIndexMap,
    /// Mapping from a non-custom dependency to its order index.
    non_custom_index_map: NonCustomReferenceMap<usize>,
    /// Information of each variable indexed by the order index.
    var_info: SmallVec<[VarInfo; 5]>,
    /// The stack of order index of visited variables. It contains
    /// all unfinished strong connected components.
    stack: SmallVec<[usize; 5]>,
    /// The stylist is used to get registered properties, and to resolve the environment to
    /// substitute `env()` variables.
    stylist: &'a Stylist,
    /// The computed context is used to get inherited custom properties, compute registered
    /// custom properties, and apply prioritary properties.
    computed_context: &'a mut computed::Context<'b>,
    /// The cascade owns prioritary-property application; when a `NonCustom` node (or a
    /// color-scheme-dependent custom property) becomes resolvable, we apply the corresponding
    /// prioritary property directly through it.
    cascade: &'a mut Cascade<'c>,
    /// The declarations, needed to apply prioritary properties.
    decls: &'a Declarations<'d>,
    /// Shorthand cache, needed to apply prioritary properties.
    cache: &'a mut ShorthandsWithPropertyReferencesCache,
}

impl<'a, 'b: 'a, 'c, 'd> Context<'a, 'b, 'c, 'd> {
    fn reset(&mut self) {
        self.count = 0;
        self.index_map.clear();
        self.non_custom_index_map = Default::default();
        self.var_info.clear();
        self.stack.clear();
    }

    fn map(&self) -> &ComputedSubstitutionFunctions {
        &self.computed_context.builder.substitution_functions
    }

    fn map_mut(&mut self) -> &mut ComputedSubstitutionFunctions {
        &mut self.computed_context.builder.substitution_functions
    }

    /// Marks a given `name` as being in a loop.
    fn handle_loop(&mut self, name: &VarType) {
        match name {
            VarType::Attr(name, namespace) => {
                self.computed_context
                    .builder
                    .substitution_functions
                    .remove_attr(name, namespace);
            },
            VarType::Custom(name) => {
                // This variable is in a loop. Resolve to invalid.
                handle_invalid_at_computed_value_time(
                    name,
                    self.stylist.get_custom_property_registration(name),
                    self.computed_context,
                );
            },
            VarType::NonCustom(non_custom) => {
                self.computed_context
                    .builder
                    .invalid_non_custom_properties
                    .insert(non_custom.to_prioritary_id().to_longhand());
            },
        }
    }

    /// Applies a prioritary property (and its dependencies) while resolving custom properties.
    ///
    /// The in-progress map lives outside `computed_context` during traversal; we move it into
    /// `computed_context.builder.substitution_functions` so the prioritary declaration's `var()`
    /// references resolve against the custom properties resolved so far, then take it back out.
    fn apply_prioritary_property(
        &mut self,
        id: PrioritaryPropertyId,
        attr_tracker: &mut AttributeTracker,
    ) {
        self.cascade.ensure_prioritary_property(
            self.computed_context,
            self.decls,
            self.cache,
            attr_tracker,
            id,
        );
    }

/// Traverse a single dependency `var` of the variable at order index `index`, updating its
/// `lowlink`/`self_ref` from the result.
fn visit_link<'a, 'b, 'c, 'd>(
    var: VarType,
    index: usize,
    non_custom_references: &NonCustomPropertyReferences,
    context: &mut Context<'a, 'b, 'c, 'd>,
    lowlink: &mut usize,
    self_ref: &mut bool,
    attr_tracker: &mut AttributeTracker,
) {
    let next_index = match traverse(var, non_custom_references, context, attr_tracker) {
        Some(index) => index,
        // There is nothing to do if the next variable has been
        // fully resolved at this point.
        None => return,
    };
    let next_info = &context.var_info[next_index];
    if next_index > index {
        // The next variable has a larger index than us, so it
        // must be inserted in the recursive call above. We want
        // to get its lowlink.
        *lowlink = cmp::min(*lowlink, next_info.lowlink);
    } else if next_index == index {
        *self_ref = true;
    } else if next_info.var.is_some() {
        // The next variable has a smaller order index and it is
        // in the stack, so we are at the same component.
        *lowlink = cmp::min(*lowlink, next_index);
    }
}

/// This function combines the traversal for cycle removal and value
/// substitution. It returns either a signal None if this variable
/// has been fully resolved (to either having no reference or being
/// marked invalid), or the order index for the given name.
///
/// When it returns, the variable corresponds to the name would be
/// in one of the following states:
/// * It is still in context.stack, which means it is part of an
///   potentially incomplete dependency circle.
/// * It has been removed from the map.  It can be either that the
///   substitution failed, or it is inside a dependency circle.
///   When this function removes a variable from the map because
///   of dependency circle, it would put all variables in the same
///   strong connected component to the set together.
/// * It doesn't have any reference, because either this variable
///   doesn't have reference at all in specified value, or it has
///   been completely resolved.
/// * There is no such variable at all.
fn traverse<'a, 'b, 'c, 'd>(
    var: VarType,
    references_from_non_custom_properties: &NonCustomPropertyReferences,
    context: &mut Context<'a, 'b, 'c, 'd>,
    attribute_tracker: &mut AttributeTracker,
) -> Option<usize> {
    // Some shortcut checks.
    // The non-custom (font/line-height/color-scheme) dependencies of this value, carried out
    // of the match so we can create the corresponding nodes once we've pushed this variable.
    let mut value_non_custom_refs = ReferenceFlags::empty();
    let mut registered = false;
    let value = match var {
        VarType::Custom(ref name) | VarType::Attr(ref name, _) => {
            let map = &context.computed_context.builder.substitution_functions;
            let (registration, value, kind) = if matches!(var, VarType::Custom(..)) {
                let registration = context.stylist.get_custom_property_registration(name);
                (
                    registration,
                    map.get_var(registration, name)?.as_universal()?,
                    SubstitutionFunctionKind::Var,
                )
            } else {
                // `attr()` is always treated as unregistered.
                (
                    PropertyDescriptors::unregistered(),
                    map.get_attr(name, var.namespace().unwrap())?
                        .as_universal()?,
                    SubstitutionFunctionKind::Attr,
                )
            };
            let is_root = context.computed_context.is_root_element();
            value_non_custom_refs = find_non_custom_references(registration, value, is_root);
            registered = !registration.is_universal();
            let has_dependency = value
                .references
                .flags
                .intersects(ReferenceFlags::ATTR | ReferenceFlags::VAR)
                || !value_non_custom_refs.is_empty();
            // Nothing to resolve.
            if !has_dependency {
                debug_assert!(
                    !value.references.flags.intersects(ReferenceFlags::ENV),
                    "Should've been handled earlier"
                );
                if kind == SubstitutionFunctionKind::Attr || registered {
                    // We might still need to compute the value if this is not an universal
                    // registration but we thought it had a dependency during the cascade and it
                    // turned out not to. Note that if this was already computed we would've
                    // bailed out in the as_universal() check.
                    let value = value.clone();
                    substitute_references_if_needed_and_apply(
                        name,
                        var.namespace(),
                        &value,
                        context.stylist,
                        context.computed_context,
                        attribute_tracker,
                    );
                }
                return None;
            }

            // Has this variable been visited?
            let index_map = if kind == SubstitutionFunctionKind::Var {
                &mut context.index_map.var
            } else {
                context
                    .index_map
                    .attr
                    .entry(var.namespace().unwrap().clone())
                    .or_default()
            };
            match index_map.entry_ref(name) {
                EntryRef::Occupied(entry) => {
                    return Some(*entry.get());
                },
                EntryRef::Vacant(entry) => {
                    entry.insert(context.count);
                },
            }
            // Hold a strong reference to the value so that we don't
            // need to keep reference to context.map.
            Some(value.clone())
        },
        VarType::NonCustom(ref non_custom) => {
            let entry = &mut context.non_custom_index_map[*non_custom];
            if let Some(v) = entry {
                return Some(*v);
            }
            *entry = Some(context.count);
            None
        },

    // color-scheme), as computed by `find_non_custom_references` above.
    let is_root = context.computed_context.is_root_element();
    if registered && !value_non_custom_refs.is_empty() {
        value_non_custom_refs.for_each_non_custom(is_root, |r| {
            visit_link(
                VarType::NonCustom(r),
                index,
                references_from_non_custom_properties,
                context,
                &mut lowlink,
                &mut self_ref,
                attribute_tracker,
            );
        });
    }
} else if let VarType::NonCustom(non_custom) = var {
    // line-height's resolution depends on font-size's, so its node has a graph edge to the
    // font-size node. This is needed for cycle detection (not just application order, which
    // `prioritary_property_dependencies(LineHeight)` handles): it puts the line-height node
    // in the same strongly-connected component as a font-size<->custom cycle, so the node
    // doesn't apply line-height (and, transitively, font-size) before that cycle is
    // removed.
    //
    // TODO(emilio): I think the right fix for this is
    // s/SingleNonCustomReference/PrioritaryPropertyId in VarType::NonCustom.
    if non_custom == SingleNonCustomReference::LhUnits {
        visit_link(
            VarType::NonCustom(SingleNonCustomReference::FontUnits),
            index,
            references_from_non_custom_properties,
            context,
            &mut lowlink,
            &mut self_ref,
            attribute_tracker,
        );
    }
    let entry = &references_from_non_custom_properties[non_custom];
    if let Some(values) = entry.as_ref() {
        for (longhand_id, value) in values {
            // Traverse the non-custom property's declaration value(s), creating edges to
            // the custom properties they reference (directly or through a used fallback)
            // that might cycle back to this node. Note we traverse unregistered/universal
            // references too: while their own font-relative units are textual (resolved
            // against the parent, see `find_non_custom_references`), they may chain to a
            // registered property that does cycle back.
            let property_id = value.substitution_property_id(*longhand_id);
            let value = &value.variable_value;
            visit_value_references(
                &value.references,
                &value.url_data,
                Some(property_id),
                index,
                references_from_non_custom_properties,
                context,
                &mut lowlink,
                &mut self_ref,
                attribute_tracker,
                &mut Default::default(),
            );
        }
    }
}

context.var_info[index].lowlink = lowlink;
if lowlink != index {
    // This variable is in a loop, but it is not the root of this strong connected
    // component. We simply return for now, and the root would remove it from the map.
    //
    // This cannot be removed from the map here, because otherwise the shortcut check at the
    // beginning of this function would return the wrong value.
    return Some(index);
}

// This is the root of a strong-connected component.
let mut in_loop = self_ref;
loop {
    let var_index = context
        .stack
        .pop()
        .expect("The current variable should still be in stack");
    let var_info = &mut context.var_info[var_index];
    // We should never visit the variable again, so it's safe to take the name away.
    let var_name = var_info
        .var
        .take()
        .expect("Variable should not be popped from stack twice");
    if var_index != index {
        // Anything here is in a loop which can traverse to the node we are handling, so
        // it's invalid at computed-value time.
        in_loop = true;
    }
    if in_loop {
        context.handle_loop(&var_name);
    }
    if var_index == index {
        debug_assert_eq!(var_name, var);
        break;
    }
}

if in_loop {
    return None;
}

// Not in a loop, apply the value.
match var {
    VarType::Custom(ref name) | VarType::Attr(ref name, _) => {
        if let Some(ref v) = value {
            // We know we're not in a loop now, perform substitution.
            // TODO(emilio): Merge with the cycle detection loop instead?
            substitute_references_if_needed_and_apply(
                name,
                var.namespace(),
                v,
                context.stylist,
                context.computed_context,
                attribute_tracker,
            );
        }
    },
    VarType::NonCustom(non_custom) => {
        context.apply_prioritary_property(non_custom.to_prioritary_id(), attribute_tracker);
    },
}
// All resolved, so return the signal value.
None

pub(crate) fn parse_typed_value(
    &self,
    input: &mut Parser,
    url_data: &UrlExtraData,
    property_id: Option<PropertyIdRef>,
) -> Result<SpecifiedRegisteredValue, ()> {
    let AttributeType::Type(syntax) = &self.kind else {
        return Err(());
    };
    SpecifiedRegisteredValue::parse(
        input,
        syntax,
        url_data,
        None,
        AllowComputationallyDependent::Yes,
        AttrTaint::default(),
        property_id,
    )
    .map_err(|_| ())
}

/// Attribute values may reference other substitution functions we may need to process.
/// See step 6: https://drafts.csswg.org/css-values-5/#attr-substitution
pub fn get_attr_value_for_cycle_resolution(
    name: &Name,
    attribute_data: &AttributeData,
    url_data: &UrlExtraData,
    attribute_tracker: &mut AttributeTracker,
) -> Result<ComputedRegisteredValue, ()> {
    let namespace = match attribute_data.namespace {
        ParsedNamespace::Known(ref ns) => ns,
        ParsedNamespace::Unknown => return Err(()),
    };
    let attr = LocalName::with_name(name, |local_name| {
        attribute_tracker.query(local_name, namespace).ok_or(())
    })?;
    let mut parser = Parser::new(&attr);
    // TODO(Bug 2021110): Support namespaced attributes in chained references.
    let value = VariableValue::parse(&mut parser, None, url_data).map_err(|_| ())?;
    Ok(ComputedRegisteredValue::universal(Arc::new(value)))
}

/// Replace `var()`, `env()`, and `attr()` functions in a pre-existing variable value.
pub fn substitute_references_if_needed_and_apply(
    name: &Name,
    namespace: Option<&Namespace>,
    value: &Arc<VariableValue>,
    stylist: &Stylist,
    context: &mut computed::Context,
    attribute_tracker: &mut AttributeTracker,
) {
    let is_var = namespace.is_none();
    let registration = stylist.get_custom_property_registration(name);
    if is_var && !value.has_references() && registration.is_universal() {
        // Trivial path: no references and no need to compute the value, just apply it directly.
        let computed_value = ComputedRegisteredValue::universal(Arc::clone(value));
        context
            .builder
            .substitution_functions
            .insert_var(registration, name, computed_value);
        return;
    }

    let url_data = &value.url_data;
    let mut state = SubstitutionState::default();
    if is_var {
        state.names.push(name);
    }
    let substitution = substitute_internal(
        value,
        Some(PropertyIdRef::from(name)),
        &context.builder.substitution_functions,
        stylist,
        context,
        attribute_tracker,
        &mut state,
        None,
        false,
    );
    let substitution = if is_var && state.cyclic_names.contains(&name) {
        Err(())
    } else {
        substitution
    };
    drop(state);

    let Ok(substitution) = substitution else {
        if is_var {
            handle_invalid_at_computed_value_time(name, registration, context);
        } else if let Some(namespace) = namespace {
            context
                .builder
                .substitution_functions
                .remove_attr(name, namespace);
        }
        return;
    };

    // If variable fallback results in a wide keyword, deal with it now.
    let animation_tainted = substitution.animation_tainted;
    if is_var {
        let css_wide_kw = {
            let mut input = Parser::new(&substitution.css);
            input.try_parse(CSSWideKeyword::parse)
        };
        if let Ok(keyword) = css_wide_kw {
            let uses_initial = context.is_root_element()
                || keyword == CSSWideKeyword::Initial
                || (keyword != CSSWideKeyword::Inherit && !registration.inherits());
            if uses_initial {
                context
                    .builder
                    .substitution_functions
                    .remove_var(registration, name);
            }
            if let Some(value) =
                substituted_css_wide_keyword_value(name, keyword, registration, stylist, context)
            {
                context
                    .builder
                    .substitution_functions
                    .insert_var(registration, name, value);
            } else if !uses_initial {
                context
                    .builder
                    .substitution_functions
                    .remove_var(registration, name);
            }
            if animation_tainted {
                let value = context.builder.substitution_functions.get_var(registration, name).cloned();
                if let Some(mut value) = value {
                    value.animation_tainted = true;
                    context.builder.substitution_functions.insert_var(registration, name, value);
                }
            }
            return;
        }
    }

    match namespace {
        None => {
            let value = match substitution.into_value(
                url_data,
                registration,
                context,
                Some(PropertyIdRef::from(name)),
            ) {
                Ok(v) => v,
                Err(()) => {
                    handle_invalid_at_computed_value_time(name, registration, context);
                    return;
                },
            };
            context
                .builder
                .substitution_functions
                .insert_var(registration, name, value);
        },
        Some(namespace) => {
            let mut value =
                ComputedRegisteredValue::universal(Arc::new(VariableValue::new_resolved(
                    substitution.css.into_owned(),
                    url_data,
                    substitution.first_token_type,
                    substitution.last_token_type,
                )));
            value.attr_tainted |= substitution.attr_tainted;
            context
                .builder
                .substitution_functions
                .insert_attr(name, namespace, value);
        },
    }
}

#[derive(Default)]
struct SubstitutionState<'a> {
    names: SmallVec<[&'a Name; 8]>,
    cyclic_names: SmallVec<[&'a Name; 8]>,
}

enum RegisteredSubstitutionDefault {
    NotDefaulted,
    Defaulted(Option<ComputedRegisteredValue>),
}

#[derive(Default, Debug)]
struct Substitution<'a> {
    css: Cow<'a, str>,
    first_token_type: TokenSerializationType,
    last_token_type: TokenSerializationType,
    attr_tainted: bool,
    animation_tainted: bool,
}

fn do_substitute_chunk<'a>(
    css: &'a str,
    start: usize,
    end: usize,
    first_token_type: TokenSerializationType,
    last_token_type: TokenSerializationType,
    url_data: &UrlExtraData,
    property_id: Option<PropertyIdRef>,
    substitution_functions: &'a ComputedSubstitutionFunctions,
    stylist: &Stylist,
    computed_context: &computed::Context,
    references: &'a [SubstitutionFunctionReference],
    attribute_tracker: &mut AttributeTracker,
    seen: &mut SubstitutionState<'a>,
    mut attr_taint: Option<&mut AttrTaint>,
    suppress_animation_taint_sink: bool,
) -> Result<Substitution<'a>, ()> {
    if start == end {
        // Empty string. Easy.
        return Ok(Substitution::default());
    }
    // Easy case: no references involved.
    if references.is_empty() {
        let result = &css[start..end];
        return Ok(Substitution::new(
            Cow::Borrowed(result),
            first_token_type,
            last_token_type,
            Default::default(),
        ));
    }

    let mut substituted = ComputedValue::empty(url_data);
    let mut next_token_type = first_token_type;
    let mut cur_pos = start;
    let mut attr_tainted = false;
    let mut animation_tainted = false;
    let references = references.iter();
    for reference in references {
        if reference.start != cur_pos {
            substituted.push(
                &css[cur_pos..reference.start],
                next_token_type,
                reference.prev_token_type,
                /* attr_taint */ None,
            )?;
        }

        let substitution = substitute_one_reference(
            css,
            url_data,
            property_id,
            substitution_functions,
            reference,
            stylist,
            computed_context,
            attribute_tracker,
            seen,
            suppress_animation_taint_sink,
        )?;

        // Optimize the property: var(--...) case to avoid allocating at all.
        if reference.start == start && reference.end == end {
            if let Some(taint) = attr_taint.filter(|_| substitution.attr_tainted) {
                taint.push(start, substitution.css.len());
            }
            return Ok(substitution);
        }

        substituted.push(
            &substitution.css,
            substitution.first_token_type,
            substitution.last_token_type,
            attr_taint
                .as_deref_mut()
                .filter(|_| substitution.attr_tainted),
        )?;
        attr_tainted |= substitution.attr_tainted;
        animation_tainted |= substitution.animation_tainted;
        next_token_type = reference.next_token_type;
        cur_pos = reference.end;
    }
    // Push the rest of the value if needed.
    if cur_pos != end {
        substituted.push(
            &css[cur_pos..end],
            next_token_type,
            last_token_type,
            /* attr_taint */ None,
        )?;
    }
    substituted.explicitly_animation_tainted = animation_tainted;
    Ok(Substitution::from_value(substituted, attr_tainted))
}

let substitution: Option<_> = match reference.substitution_kind {
    SubstitutionFunctionKind::Var => {
        let registration = stylist.get_custom_property_registration(&reference.name);
        match substitution_functions.get_var(registration, &reference.name) {
            None => None,
            // If the referenced value is itself still unresolved (i.e. it has references), we
            // are substituting against a partially-resolved map -- this happens while applying
            // a prioritary property in the middle of custom-property resolution. Resolve it
            // recursively, guarding against cycles (which the resolver will also remove, but it
            // may not have gotten to this variable yet).
            Some(v) => match v.as_universal() {
                Some(u) if u.has_references() => {
                    if let Some(index) =
                        seen.names.iter().position(|name| *name == &reference.name)
                    {
                        for name in &seen.names[index..] {
                            if !seen.cyclic_names.contains(name) {
                                seen.cyclic_names.push(*name);
                            }
                        }
                        // Cycle: the primary is guaranteed-invalid, so fall through to the
                        // fallback (if any), like any other invalid primary.
                        None
                    } else {
                        seen.names.push(&reference.name);
                        let result = substitute_internal(
                            u,
                            property_id,
                            substitution_functions,
                            stylist,
                            computed_context,
                            attribute_tracker,
                            seen,
                            /* attr_taint */ None,
                            true,
                        );
                        seen.names.pop();
                        if seen.cyclic_names.contains(&&reference.name) {
                            invalid_at_computed_value_time_value(
                                &reference.name,
                                registration,
                                stylist,
                                computed_context,
                            )
                            .map(|value| {
                                Substitution::from_value(
                                    value.to_variable_value(),
                                    value.attr_tainted,
                                )
                            })
                        } else {
                            match result {
                                Ok(mut substitution) => {
                                    substitution.attr_tainted |= v.attr_tainted;
                                    substitution.animation_tainted |= v.animation_tainted;
                                    match substitution.registered_default(
                                        &reference.name,
                                        registration,
                                        &u.url_data,
                                        stylist,
                                        computed_context,
                                    ) {
                                        RegisteredSubstitutionDefault::Defaulted(value) => {
                                            value.map(|value| {
                                                Substitution::from_value(
                                                    value.to_variable_value(),
                                                    value.attr_tainted,
                                                )
                                            })

                ParsedNamespace::Unknown => None,
            };
            namespace
                .and_then(|namespace| {
                    LocalName::with_name(&reference.name, |local_name| {
                        attribute_tracker.query(local_name, namespace)
                    })
                })
                .map_or_else(
                    || {
                        // Special case when fallback and <attr-type> are omitted.
                        // See FAILURE: https://drafts.csswg.org/css-values-5/#attr-substitution
                        if reference.fallback.is_none()
                            && reference.attribute_data.kind == AttributeType::None
                        {
                            simple_attr_subst("")
                        } else {
                            None
                        }
                    },
                    |attr| {
                        let attr = if let AttributeType::Type(_) = &reference.attribute_data.kind {
                            // If we're evaluating a container query, we haven't run the cascade
                            // and populated substitution_functions.attributes, so we can't do the
                            // get_attr() lookup here.
                            // TODO: This means chained attr() references will not work reliably in
                            // container style queries:
                            // https://bugzilla.mozilla.org/show_bug.cgi?id=2028861
                            if computed_context.in_container_query {
                                attr
                            } else {
                                substitution_functions
                                    .get_attr(&reference.name, namespace?)
                                    .map(|v| v.to_variable_value())?
                                    .css
                            }
                        } else {
                            attr
                        };
                        let mut parser = Parser::new(&attr);
                        match &reference.attribute_data.kind {
                            AttributeType::Unit(unit) => {
                                let css = {
                                    let mut s = String::from(parse_attr_number(&mut parser).ok()?);
                                    s.push_str(unit.as_ref());
                                    s
                                };
                                let serialization = match unit {
                                    AttrUnit::Number => TokenSerializationType::Number,
                                    AttrUnit::Percentage => TokenSerializationType::Percentage,
                                    _ => TokenSerializationType::Dimension,
                                };
                                let value =
                                    ComputedValue::new(css, url_data, serialization, serialization);
                                Some(Substitution::from_value(
                                    value, /* attr_tainted */ true,
                                ))
                            },
                            AttributeType::Type(_) => {
                                let value = reference
                                    .attribute_data
                                    .parse_typed_value(&mut parser, url_data, property_id)
                                    .ok()?;
                                let value = value.to_variable_value();
                                Some(Substitution::from_value(
                                    value, /* attr_tainted */ true,
                                ))
                            },
                            AttributeType::RawString | AttributeType::None => {
                                simple_attr_subst(&attr)
                            },
                            AttributeType::Invalid => None,
                        }
                    },
                )
        },
    };

    let substitution = substitution.filter(|value| {
        !(reference.substitution_kind == SubstitutionFunctionKind::Var
            && value.animation_tainted
            && !suppress_animation_taint_sink
            && matches!(property_id, Some(PropertyIdRef::NonCustom(id)) if !id.is_animatable()))
    });
    if let Some(s) = substitution {
        return Ok(s);
    }

    let Some(ref fallback) = reference.fallback else {
        return Err(());
    };

    do_substitute_chunk(
        css,
        fallback.start.get(),
        reference.end - 1, // Skip the closing parenthesis of the reference value.
        fallback.first_token_type,
        fallback.last_token_type,
        url_data,
        property_id,
        substitution_functions,
        stylist,
        computed_context,
        &fallback.references.refs,
        attribute_tracker,
        seen,
        /* attr_taint */ None,
        suppress_animation_taint_sink,
    )
}

fn substitute_internal<'a>(
    variable_value: &'a VariableValue,
    property_id: Option<PropertyIdRef>,
    substitution_functions: &'a ComputedSubstitutionFunctions,
    stylist: &Stylist,
    computed_context: &computed::Context,
    attribute_tracker: &mut AttributeTracker,
    seen: &mut SubstitutionState<'a>,
    attr_taint: Option<&mut AttrTaint>,
    suppress_animation_taint_sink: bool,
) -> Result<Substitution<'a>, ()> {
    let mut result = do_substitute_chunk(
        &variable_value.css,
        /* start = */ 0,
        /* end = */ variable_value.css.len(),
        variable_value.first_token_type,
        variable_value.last_token_type,
        &variable_value.url_data,
        property_id,
        substitution_functions,
        stylist,
        computed_context,
        &variable_value.references.refs,
        attribute_tracker,
        seen,
        attr_taint,
        suppress_animation_taint_sink,
    )?;
    result.animation_tainted |= variable_value.explicitly_animation_tainted;
    Ok(result)
}

/// Replace var(), env(), and attr() functions, returning the resulting CSS string.
pub fn substitute<'a>(
    variable_value: &'a VariableValue,
    property_id: Option<PropertyIdRef>,
    substitution_functions: &'a ComputedSubstitutionFunctions,
    stylist: &Stylist,
    computed_context: &computed::Context,
    attribute_tracker: &mut AttributeTracker,
) -> Result<SubstitutionResult<'a>, ()> {
    debug_assert!(variable_value.has_references());
    let mut attr_taint = AttrTaint::default();
    let v = substitute_internal(
        variable_value,
        property_id,
        substitution_functions,
        stylist,
        computed_context,
        attribute_tracker,
        &mut SubstitutionState::default(),
        Some(&mut attr_taint),
        false,
    )?;
    Ok(SubstitutionResult {
        css: v.css,
        attr_taint,
    })
}

/// An unparsed property value that contains `var()` functions.
#[derive(Debug, Eq, PartialEq, ToShmem)]
pub struct UnparsedValue {
    /// The variable value, references and so on.
    pub(super) variable_value: custom_properties::VariableValue,
    /// The shorthand this came from.
    from_shorthand: Option<ShorthandId>,
}

impl UnparsedValue {
    pub(crate) fn substitution_property_id(&self, longhand_id: LonghandId) -> PropertyIdRef<'static> {
        PropertyIdRef::from(match self.from_shorthand {
            Some(shorthand_id) => NonCustomPropertyId::from(shorthand_id),
            None => NonCustomPropertyId::from(longhand_id),
        })
    }
}

impl ToCss for UnparsedValue {
    fn to_css<W>(&self, dest: &mut CssWriter<W>) -> fmt::Result
    where
        W: Write,
    {
        // https://drafts.csswg.org/css-variables/#variables-in-shorthands
        if self.from_shorthand.is_none() {
            self.variable_value.to_css(dest)?;
        }
        Ok(())
    }
}

impl ToTyped for UnparsedValue {
    fn to_typed(&self, dest: &mut ThinVec<TypedValue>) -> Result<(), ()> {
        if self.from_shorthand.is_none() {
            self.variable_value.to_typed(dest)?;
            return Ok(());
        }
        Err(())
    }
}

/// A simple cache for properties that come from a shorthand and have variable
/// references.
///
/// Entries retain their source because rollback can select different declarations
/// of the same shorthand for different longhands.
pub type ShorthandsWithPropertyReferencesCache =
    FxHashMap<(ShorthandId, LonghandId), (Arc<UnparsedValue>, PropertyDeclaration)>;

impl VariableDeclaration {
    fn substitute_variables<'cache>(
        &self,
        substitution_functions: &ComputedSubstitutionFunctions,
        stylist: &Stylist,
        computed_context: &computed::Context,
        shorthand_cache: &'cache mut ShorthandsWithPropertyReferencesCache,
        attribute_tracker: &mut AttributeTracker,
    ) -> Cow<'cache, PropertyDeclaration> {
        let longhand_id = self.id;
        let unparsed = &self.value;
        let invalid_at_computed_value_time = || {
            let keyword = if longhand_id.inherited() {
                CSSWideKeyword::Inherit
            } else {
                CSSWideKeyword::Initial
            };
            Cow::Owned(PropertyDeclaration::css_wide_keyword(longhand_id, keyword))
        };

        if computed_context
            .builder
            .invalid_non_custom_properties
            .contains(longhand_id)
        {
            return invalid_at_computed_value_time();
        }

        if let Some(shorthand_id) = unparsed.from_shorthand {
            let key = (shorthand_id, longhand_id);
            if shorthand_cache
                .get(&key)
                .is_some_and(|(source, _)| Arc::ptr_eq(source, unparsed))
            {
                // FIXME: This double lookup should be avoidable, but rustc
                // doesn't like that, see:
                //
                // https://github.com/rust-lang/rust/issues/82146
                return Cow::Borrowed(&shorthand_cache[&key].1);
            }
        }

        let property_id = unparsed.substitution_property_id(longhand_id);

        let SubstitutionResult { css, attr_taint } = match custom_properties::substitute(
            &unparsed.variable_value,
            Some(property_id),
            substitution_functions,
            stylist,
            computed_context,
            attribute_tracker,
        ) {
            Ok(css) => css,
            Err(..) => return invalid_at_computed_value_time(),
        };

        // As of this writing, only the base URL is used for property
        // values.
        //
        // NOTE(emilio): we intentionally pase `None` as the rule type here.
        // If something starts depending on it, it's probably a bug, since
        // it'd change how values are parsed depending on whether we're in a
        // @keyframes rule or not, for example... So think twice about
        // whether you want to do this!
        //
        // FIXME(emilio): ParsingMode is slightly fishy...
        let mut context = ParserContext::new(
            Origin::Author,
            &unparsed.variable_value.url_data,
            None,
            ParsingMode::DEFAULT,
            computed_context.quirks_mode,
            /* namespaces = */ Default::default(),
            None,
            None,
            attr_taint,
        );

        let mut input = Parser::new(&css);
        input.skip_whitespace();

        if let Ok(keyword) = input.try_parse(CSSWideKeyword::parse) {
            return Cow::Owned(PropertyDeclaration::css_wide_keyword(longhand_id, keyword));
        }

        let shorthand = match unparsed.from_shorthand {
            None => {
                return match context.with_property_declaration(property_id, |context| {
                    input.parse_entirely(|input| longhand_id.parse_value(context, input))
                }) {
                    Ok(decl) => Cow::Owned(decl),
                    Err(..) => invalid_at_computed_value_time(),
                };
            },
            Some(shorthand) => shorthand,
        };

        let mut decls = SourcePropertyDeclaration::default();
        // parse_into takes care of doing `parse_entirely` for us.
        if context
            .with_property_declaration(property_id, |context| {
                shorthand.parse_into(&mut decls, context, &mut input)
            })
            .is_err()
        {
            return invalid_at_computed_value_time();
        }
